🏁 Script executed:

```shell
#!/bin/bash
# Description: Demonstrate that a newly-created non-configurable data property
# cannot later be redefined as an accessor property.

node - <<'NODE'
const target = {};
Object.defineProperty(target, 'sessionStorage', {
  value: {},
  writable: true,
});

try {
  Object.defineProperty(target, 'sessionStorage', {
    get() {
      throw new Error('storage unavailable');
    },
    configurable: true,
  });
  console.log('unexpected: redefine succeeded');
} catch (error) {
  console.log(`${error.name}: ${error.message}`);
}
NODE
