Repository: Ultimate-Multisite/gratis-ai-agent

Length of output: 129

---



</details>

**Add `configurable: true` to the initial `sessionStorage` mock and wrap later accessor redefinitions in try-finally.**

When `Object.defineProperty` creates a property without `configurable: true`, it becomes non-configurable by default. Attempting to redefine it as an accessor (lines 69-82, 129-142) will throw `TypeError: Cannot redefine property: sessionStorage` in non-jsdom environments. Use try-finally to ensure the global is restored even if a test fails, preventing test pollution.

<details>
<summary>Proposed fix</summary>

```diff
 Object.defineProperty( global, 'sessionStorage', {
 	value: sessionStorageMock,
+	configurable: true,
 	writable: true,
 } );
@@
 	test( 'does not throw when sessionStorage is unavailable', () => {
 		const original = global.sessionStorage;
-		Object.defineProperty( global, 'sessionStorage', {
-			get() {
-				throw new Error( 'storage unavailable' );
-			},
-			configurable: true,
-		} );
-		expect( () => setActiveJob( 1, 'job_x' ) ).not.toThrow();
-		Object.defineProperty( global, 'sessionStorage', {
-			value: original,
-			configurable: true,
-			writable: true,
-		} );
+		try {
+			Object.defineProperty( global, 'sessionStorage', {
+				get() {
+					throw new Error( 'storage unavailable' );
+				},
+				configurable: true,
+			} );
+			expect( () => setActiveJob( 1, 'job_x' ) ).not.toThrow();
+		} finally {
+			Object.defineProperty( global, 'sessionStorage', {
+				value: original,
+				configurable: true,
+				writable: true,
+			} );
+		}
 	} );
@@
 	test( 'returns an empty object when sessionStorage is unavailable', () => {
 		const original = global.sessionStorage;
-		Object.defineProperty( global, 'sessionStorage', {
-			get() {
-				throw new Error( 'storage unavailable' );
-			},
-			configurable: true,
-		} );
-		expect( getActiveJobs() ).toEqual( {} );
-		Object.defineProperty( global, 'sessionStorage', {
-			value: original,
-			configurable: true,
-			writable: true,
-		} );
+		try {
+			Object.defineProperty( global, 'sessionStorage', {
+				get() {
+					throw new Error( 'storage unavailable' );
+				},
+				configurable: true,
+			} );
+			expect( getActiveJobs() ).toEqual( {} );
+		} finally {
+			Object.defineProperty( global, 'sessionStorage', {
+				value: original,
+				configurable: true,
+				writable: true,
+			} );
+		}
 	} );
```

</details>

