### MEDIUM: coderabbit (coderabbitai[bot])
**File**: `src/utils/active-jobs-storage.js:30`
_⚠️ Potential issue_ | _🟠 Major_

**Normalize parsed storage before using it.**

`JSON.parse()` can return valid non-map values like `null` or an array. That makes `getActiveJobs()` violate its `{}` fallback contract and can crash restoration callers using `Object.entries()`.



<details>
<summary>🛠️ Proposed fix</summary>

```diff
 const STORAGE_KEY = 'gratisAiAgent_activeJobs';
+
+function parseActiveJobs( raw ) {
+	if ( ! raw ) {
+		return {};
+	}
+	const parsed = JSON.parse( raw );
+	return parsed && typeof parsed === 'object' && ! Array.isArray( parsed )
+		? parsed
+		: {};
+}

 export function setActiveJob( sessionId, jobId ) {
 	try {
 		const raw = sessionStorage.getItem( STORAGE_KEY );
-		const jobs = raw ? JSON.parse( raw ) : {};
+		const jobs = parseActiveJobs( raw );
 		jobs[ sessionId ] = jobId;
 		sessionStorage.setItem( STORAGE_KEY, JSON.stringify( jobs ) );
 	} catch {
@@
 		if ( ! raw ) {
 			return;
 		}
-		const jobs = JSON.parse( raw );
+		const jobs = parseActiveJobs( raw );
 		delete jobs[ sessionId ];
@@
 export function getActiveJobs() {
 	try {
 		const raw = sessionStorage.getItem( STORAGE_KEY );
-		return raw ? JSON.parse( raw ) : {};
+		return parseActiveJobs( raw );
 	} catch {
 		return {};
 	}
 }
```

</details>


Also applies to: 52-53, 75-76

